{
  "ledger": {
    "p1:e0": {
      "state": "no_research",
      "fact_ids": [],
      "note": "제목성 문단('CUDA 버전')으로 연구 내용이 없으며, 다음 요소(p1:e1)의 nvcc 버전 출력에 대한 표제에 해당한다."
    },
    "p1:e1": {
      "state": "represented",
      "fact_ids": ["P0001F0008", "P0001F0009"],
      "note": "nvcc --version 실행 출력문으로, release 13.3 / V13.3.73(P0001F0008)과 빌드 시점 'Built on Tue_Jun__9_14:30:19_Pacific_Daylight_Time_2026'(P0001F0009)이 실제 필드에 보존되었다."
    },
    "p1:e2": {
      "state": "represented",
      "fact_ids": ["P0001F0002"],
      "note": "'lirpa_forward_backward_fc_array.cpp를 CUDA로 재작성하기'라는 주제 표제로, P0001F0002의 재작성 접근 주장을 뒷받침하는 출처 요소 중 하나이다(p1:e5와 함께 인용)."
    },
    "p1:e3": {
      "state": "no_research",
      "fact_ids": [],
      "note": "소제목('CUDA 의 핵심')으로 연구 내용이 없으며, 뒤 요소(p1:e4)의 CUDA 핵심 설명 앞에 위치한 표제이다."
    },
    "p1:e4": {
      "state": "represented",
      "fact_ids": ["P0001F0001"],
      "note": "CUDA가 C++ 언어 기반으로 GPU 동작을 가능하게 하며, CUDA 동작이 필요한 코드만 분리 작성해도 nvcc 컴파일이 가능하다는 방법론적 이해가 P0001F0001로 보존되었다."
    },
    "p1:e5": {
      "state": "represented",
      "fact_ids": ["P0001F0002"],
      "note": "lirpa_forward_backward_fc_array.cpp의 기본 틀을 가져와 병렬 연산이 필요한 부분만 device(GPU)에서 동작하는 kernel 함수로 바꾸자는 가설적 접근이 P0001F0002로 보존되었다."
    },
    "p1:e6": {
      "state": "no_research",
      "fact_ids": [],
      "note": "진입점 함수 분석으로 넘어가려는 진행 계획/전환 문장으로, 연구 증거보다는 다음 분석 단계에 대한 방향 제시에 해당한다."
    },
    "p1:e7": {
      "state": "no_research",
      "fact_ids": [],
      "note": "'m ain'이라는 진입점 함수명 표제로, 연구 내용이 없는 라벨이다."
    },
    "p1:e8": {
      "state": "represented",
      "fact_ids": ["P0001F0003"],
      "note": "main이 epsilon을 입력받으며 시스템 호출 인자를 통해 eps 값을 변경할 수 있다는 관찰이 P0001F0003으로 보존되었다."
    },
    "p1:e9": {
      "state": "no_research",
      "fact_ids": [],
      "note": "차원 수를 임의로 바꾸는 기능 추가에 대한 개선 제안(문장)이나, 승인된 사실(P0001F0001~P0001F0009)에 대응하는 연구 증거로 보존되지 않았다."
    },
    "p1:e10": {
      "state": "represented",
      "fact_ids": ["P0001F0004"],
      "note": "main에서 self_test_relaxations와 run_xor_demo를 호출한다는 호출 흐름 정보가 P0001F0004의 관찰 항목으로 보존되었다."
    },
    "p1:e11": {
      "state": "no_research",
      "fact_ids": [],
      "note": "'self_test_relaxations 분석……'이라는 소제목으로 연구 내용이 없는 표제이다."
    },
    "p1:e12": {
      "state": "represented",
      "fact_ids": ["P0001F0004"],
      "note": "self_test_relaxations가 안정성 테스트용 코드로 전체 흐름에 큰 영향이 없다는 평가가 P0001F0004의 관찰 항목으로 보존되었다."
    },
    "p1:e13": {
      "state": "represented",
      "fact_ids": ["P0001F0005"],
      "note": "run_xor_demo가 핵심이라는 강조가 P0001F0005의 관찰 항목('run_xor_demo가 중요')으로 보존되었다."
    },
    "p1:e14": {
      "state": "no_research",
      "fact_ids": [],
      "note": "구분자('= =====')로 연구 내용이 없는 시각적 분리선이다."
    },
    "p1:e15": {
      "state": "represented",
      "fact_ids": ["P0001F0005"],
      "note": "코드가 복잡하여 cpp 처음 코드부터 복붙하면서 배열 연산이 필요한 지점을 파악하기로 한 진행 방식이 P0001F0005의 관찰 항목으로 보존되었다."
    },
    "p1:e16": {
      "state": "represented",
      "fact_ids": ["P0001F0006"],
      "note": "mat_add부터 배열을 통한 연산이 시작되어 포팅을 시도했다는 관찰이 P0001F0006으로 보존되었다."
    },
    "p1:e17": {
      "state": "represented",
      "fact_ids": ["P0001F0007"],
      "note": "mat_add가 여러 번 호출되고 메모리 할당/해제도 여러 번 발생하여 비효율적이라 판단했으나 최적화는 나중에 진행하기로 한 해석적 평가가 P0001F0007로 보존되었다."
    }
  }
}
